<div class="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-emerald-600">Planilla en revisión</p><h1 class="text-2xl font-bold"><?= htmlspecialchars($periodo['nombre']) ?></h1><p class="text-sm text-slate-500">Estado: <?= htmlspecialchars($periodo['estado']) ?><?php if(!empty($periodo['revisado_en'])): ?> · aprobada <?= htmlspecialchars($periodo['revisado_en']) ?><?php endif; ?><?php if(!empty($periodo['cerrado_en'])): ?> · cerrada <?= htmlspecialchars($periodo['cerrado_en']) ?><?php endif; ?></p></div><div class="flex flex-wrap gap-2"><?php if($periodo['estado']==='CALCULADO'): ?><a href="index.php?url=planilla_ajustes&id=<?= $periodo['id_periodo_pago'] ?>" class="rounded-xl bg-amber-400 px-4 py-2 text-sm font-semibold text-amber-950">Ajustes manuales</a><form method="post" action="index.php?url=planilla_aprobar" data-confirmar-accion="planilla-aprobar"><?= campoCsrf() ?><input type="hidden" name="id_periodo_pago" value="<?= $periodo['id_periodo_pago'] ?>"><button class="rounded-xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white">Aprobar revisión</button></form><?php elseif($periodo['estado']==='REVISADO'&&tienePermiso('planilla.cerrar')): ?><form method="post" action="index.php?url=planilla_cerrar" data-confirmar-accion="planilla-cerrar"><?= campoCsrf() ?><input type="hidden" name="id_periodo_pago" value="<?= $periodo['id_periodo_pago'] ?>"><button class="rounded-xl bg-slate-800 px-4 py-2 text-sm font-semibold text-white">Cerrar planilla</button></form><?php elseif(in_array($periodo['estado'],['CERRADO','PAGADO'],true)&&tienePermiso('planilla.cerrar')): ?><a href="index.php?url=planilla_pagos&id=<?= $periodo['id_periodo_pago'] ?>" class="rounded-xl bg-emerald-600 px-4 py-2 text-sm font-semibold text-white">Gestionar pagos</a><?php endif; ?><a href="index.php?url=planilla" class="rounded-xl border bg-white px-4 py-2 text-sm font-semibold">Volver</a></div></div>
<section class="space-y-4"><?php foreach($detalles as $d): ?><article class="rounded-2xl border bg-white p-5"><div class="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="font-bold"><?= htmlspecialchars($d['trabajador']) ?></h2><p class="text-xs text-slate-500"><?= htmlspecialchars($d['tipo'].' · '.$d['modalidad_pago']) ?></p></div><div class="text-right"><p class="text-xs text-slate-500">Neto estimado</p><p class="text-xl font-bold text-emerald-700">S/ <?= number_format((float)$d['monto_pagar'],2) ?></p></div></div><div class="mt-4 grid gap-3 sm:grid-cols-3"><div class="rounded-xl bg-blue-50 p-3 text-sm">Base<br><b>S/ <?= number_format((float)$d['monto_base'],2) ?></b></div><div class="rounded-xl bg-emerald-50 p-3 text-sm">Bonificaciones<br><b>S/ <?= number_format((float)$d['bonificaciones'],2) ?></b></div><div class="rounded-xl bg-rose-50 p-3 text-sm">Descuentos<br><b>S/ <?= number_format((float)$d['descuentos'],2) ?></b></div></div><div class="mt-4 overflow-x-auto"><table class="min-w-full text-xs"><thead class="text-left uppercase text-slate-500"><tr><th class="py-2">Concepto</th><th>Cantidad</th><th>Importe</th></tr></thead><tbody><?php foreach($d['conceptos'] as $c): ?><tr class="border-t"><td class="py-2"><?= htmlspecialchars($c['nombre']) ?></td><td><?= number_format((float)$c['cantidad'],2) ?></td><td class="font-semibold <?= (float)$c['importe']<0?'text-rose-700':'text-emerald-700' ?>">S/ <?= number_format((float)$c['importe'],2) ?></td></tr><?php endforeach; ?></tbody></table></div></article><?php endforeach; ?><?php if(!$detalles): ?><div class="rounded-2xl border bg-white p-8 text-center text-slate-500">El período todavía no tiene un borrador.</div><?php endif; ?></section>
